{
  "name": "opencode-session-analyzer",
  "version": "0.1.1",
  "description": "An OpenCode plugin for analyzing historical sessions and writing stable JSON artifacts.",
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/aahljhljhlj-ux/opencode-session-analyzer.git"
  },
  "homepage": "https://github.com/aahljhljhlj-ux/opencode-session-analyzer#readme",
  "bugs": {
    "url": "https://github.com/aahljhljhlj-ux/opencode-session-analyzer/issues"
  },
  "main": "./index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "keywords": [
    "opencode",
    "plugin",
    "session",
    "analyzer",
    "llm"
  ],
  "files": [
    "index.ts",
    "src/",
    "README.md",
    "README.zh-CN.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "vitest run",
    "typecheck": "tsc -p tsconfig.json --noEmit"
  },
  "devDependencies": {
    "@types/node": "^22.15.3",
    "typescript": "^5.8.3",
    "vitest": "^3.2.4"
  },
  "dependencies": {
    "@opencode-ai/plugin": "latest"
  }
}
